    function S:createButton(name,cb,opt)local f=box(self,40);local x=b(f,name);x.Size=UDim2.new(1,-10,1,-10);x.Position=UDim2.fromOffset(5,5);x.MouseButton1Click:Connect(function()if opt and opt.animated~=false then x.BackgroundColor3=Cgode.ThemeManager.Current.Accent;task.delay(.12,function()if x.Parent then x.BackgroundColor3=Cgode.ThemeManager.Current.Surface2 end end)end;if type(cb)=="function"then task.spawn(cb)end end);return x end
    function S:createToggle(name,default,cb)local f=box(self,40);local x=b(f,"");x.Size=UDim2.fromOffset(44,22);x.Position=UDim2.new(1,-54,.5,-11);local l=self:createText("");l.Text=name;l.Parent=f;l.Position=UDim2.fromOffset(10,0);l.Size=UDim2.new(1,-70,1,0);local v=default==true;local function r()x.BackgroundColor3=v and Cgode.ThemeManager.Current.Accent or Cgode.ThemeManager.Current.Border;x.Text=v and "✓"or""end;x.MouseButton1Click:Connect(function()v=not v;r();if cb then task.spawn(cb,v)end end);r();return {Get=function()return v end,Set=function(_,z)v=not not z;r();if cb then task.spawn(cb,v)end end} end
    function S:createSlider(name,o,cb)o=o or{};local min=o.min or 0;local max=o.max or 100;local v=o.default;if v==nil then v=o.defualt end;v=v or min;local f=box(self,58);local l=self:createText("");l.Text=name;l.Parent=f;l.Position=UDim2.fromOffset(10,0);l.Size=UDim2.new(1,-80,0,24);local val=Instance.new("TextLabel");val.BackgroundTransparency=1;val.TextColor3=Cgode.ThemeManager.Current.Muted;val.Font=Enum.Font.Gotham;val.TextSize=11;val.TextXAlignment=Enum.TextXAlignment.Right;val.Size=UDim2.fromOffset(55,24);val.Position=UDim2.new(1,-65,0,0);val.Parent=f;local bar=Instance.new("Frame");bar.BackgroundColor3=Cgode.ThemeManager.Current.Border;bar.BorderSizePixel=0;bar.Position=UDim2.fromOffset(10,34);bar.Size=UDim2.new(1,-20,0,7);bar.Parent=f;corner(bar,4);local fill=Instance.new("Frame");fill.BackgroundColor3=Cgode.ThemeManager.Current.Accent;fill.BorderSizePixel=0;fill.Size=UDim2.new();fill.Parent=bar;corner(fill,4);local hit=Instance.new("TextButton");hit.BackgroundTransparency=1;hit.Text="";hit.Size=UDim2.new(1,0,0,25);hit.Position=UDim2.fromOffset(0,-9);hit.Parent=bar;local drag=false;local step=o.step or(o.precise and .1 or 1);local function set(n,fire)n=math.max(min,math.min(max,n));n=math.floor(n/step+.5)*step;if o.precise then n=tonumber(string.format("%.4f",n))end;v=n;fill.Size=UDim2.new((n-min)/(max-min),0,1,0);val.Text=tostring(n);if fire and cb then task.spawn(cb,n)end end;local function update(x)set(min+(max-min)*math.max(0,math.min(1,(x-bar.AbsolutePosition.X)/bar.AbsoluteSize.X)),true)end;hit.InputBegan:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then drag=true;update(i.Position.X)end end);game:GetService("UserInputService").InputChanged:Connect(function(i)if drag and(i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch)then update(i.Position.X)end end);game:GetService("UserInputService").InputEnded:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then drag=false end end);set(v,false);return {Get=function()return v end,Set=function(_,z)set(z,true)end}end
