    function S:createTextBox(name,default,cb)local f=box(self,40);local x=Instance.new("TextBox");x.BackgroundTransparency=1;x.Text=tostring(default or"");x.PlaceholderText=tostring(name or"TextBox");x.TextColor3=Cgode.ThemeManager.Current.Text;x.PlaceholderColor3=Cgode.ThemeManager.Current.Muted;x.Font=Enum.Font.Gotham;x.TextSize=12;x.ClearTextOnFocus=false;x.Size=UDim2.new(1,-20,1,0);x.Position=UDim2.fromOffset(10,0);x.Parent=f;x.FocusLost:Connect(function()if cb then task.spawn(cb,x.Text)end end);return {getText=function()return x.Text end,GetText=function()return x.Text end,clearText=function()x.Text=""end,ClearText=function()x.Text=""end,setText=function(_,z)x.Text=tostring(z)end,SetText=function(_,z)x.Text=tostring(z)end}end
